using System;
using System.Collections.Generic;
using System.Text;

abstract record Address;
sealed record Mailbox(string Name, string AddressText) : Address;
sealed record AddressGroup(List<Address> Mailboxes) : Address;
sealed record AddressList(List<Address> Addresses, bool EncodingError);
sealed class AddressFailure : Exception {}
sealed class Addresses {
    static readonly HashSet<string> Phrase = ["word", "quoted", "."], DotAtomKinds = ["word", "."];
    readonly List<Token> tokens;
    int position;
    bool encodingError;
    Addresses(List<Token> tokens) { this.tokens = tokens; }
    string Peek() => position < tokens.Count ? tokens[position].Kind : "";
    void Expect(string kind) { if (Peek() != kind) throw new AddressFailure(); position++; }
    List<Token> Run(HashSet<string> kinds) {
        int start = position;
        while (kinds.Contains(Peek())) position++;
        return tokens.GetRange(start, position - start);
    }
    static bool DotAtom(List<Token> tokens) {
        if (tokens.Count % 2 == 0) return false;
        for (int i = 0; i < tokens.Count; i++) if (tokens[i].Kind != (i % 2 == 0 ? "word" : ".")) return false;
        return true;
    }
    static string AddressString(List<Token> local, List<Token> domain) {
        if (!DotAtom(local) || !DotAtom(domain)) throw new AddressFailure();
        StringBuilder result = new();
        foreach (Token token in local) result.Append(token.Text);
        result.Append('@');
        foreach (Token token in domain) result.Append(token.Text);
        return result.ToString().ToLowerInvariant();
    }
    string DisplayName(List<Token> phrase) {
        StringBuilder result = new();
        bool previous = false;
        for (int i = 0; i < phrase.Count; i++) {
            Token token = phrase[i];
            DecodedWord decoded = token.Kind == "word" ? Headers.DecodeWord(token.Text) : new DecodedWord(token.Text, false, false);
            encodingError |= decoded.Error;
            if (i > 0 && token.Spaced && !(previous && decoded.Decoded)) result.Append(' ');
            result.Append(decoded.Text); previous = decoded.Decoded;
        }
        return Headers.Collapse(result.ToString());
    }
    Address ParseAddress(bool inGroup) {
        List<Token> phrase = Run(Phrase);
        string following = Peek();
        if (following == "<") {
            position++;
            List<Token> local = Run(DotAtomKinds);
            Expect("@");
            List<Token> domain = Run(DotAtomKinds);
            Expect(">");
            return new Mailbox(DisplayName(phrase), AddressString(local, domain));
        }
        if (following == "@") { position++; return new Mailbox("", AddressString(phrase, Run(DotAtomKinds))); }
        if (following == ":" && phrase.Count > 0 && !inGroup) {
            position++;
            List<Address> mailboxes = new();
            if (Peek() != ";") {
                mailboxes.Add(ParseAddress(true));
                while (Peek() == ",") { position++; mailboxes.Add(ParseAddress(true)); }
            }
            Expect(";");
            return new AddressGroup(mailboxes);
        }
        throw new AddressFailure();
    }
    List<Address> ParseList() {
        List<Address> addresses = [ParseAddress(false)];
        while (Peek() == ",") { position++; addresses.Add(ParseAddress(false)); }
        if (position != tokens.Count) throw new AddressFailure();
        return addresses;
    }
    public static AddressList Parse(string value) {
        List<Token> tokens = Headers.Tokenize(value, false);
        if (tokens == null || tokens.Count == 0) return null;
        Addresses parser = new(tokens);
        try { List<Address> addresses = parser.ParseList(); return new AddressList(addresses, parser.encodingError); }
        catch (AddressFailure) { return null; }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

sealed record DateResult(long? Seconds, string Error);
static class Dates {
    static readonly string[] Weekdays = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"], Months = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
    static readonly int[] MonthLengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    static readonly Dictionary<string, int> Zones = new(StringComparer.Ordinal) { ["ut"] = 0, ["gmt"] = 0, ["z"] = 0, ["est"] = -300, ["edt"] = -240, ["cst"] = -360, ["cdt"] = -300, ["mst"] = -420, ["mdt"] = -360, ["pst"] = -480, ["pdt"] = -420 };
    static bool Leap(int year) => year % 4 == 0 && year % 100 != 0 || year % 400 == 0;
    static int MonthDays(int year, int month) => month == 2 && Leap(year) ? 29 : MonthLengths[month - 1];
    static int YearDays(int year) => Leap(year) ? 366 : 365;
    static int EpochDays(int year, int month, int day) {
        int days = day - 1;
        for (int current = 1970; current < year; current++) days += YearDays(current);
        for (int current = 1; current < month; current++) days += MonthDays(year, current);
        return days;
    }
    public static bool Digits(string text, params int[] lengths) => lengths.Contains(text.Length) && text.All(letter => letter >= '0' && letter <= '9');
    static bool NumericZone(string text) => text.Length == 5 && (text[0] == '+' || text[0] == '-') && Digits(text[1..], 4);
    static DateResult Failure(string text) => new(null, text);
    public static DateResult Parse(string value) {
        string text = Headers.RemoveComments(value);
        if (text == null) return Failure("bad Date syntax");
        List<string> tokens = Headers.Words(text.Replace(",", " , "));
        int weekday = -1;
        if (tokens.Count >= 3 && Weekdays.Contains(tokens[0].ToLowerInvariant()) && tokens[1] == ",") {
            weekday = Array.IndexOf(Weekdays, tokens[0].ToLowerInvariant()); tokens = tokens.GetRange(2, tokens.Count - 2);
        }
        if (tokens.Count != 5) return Failure("bad Date syntax");
        string dayText = tokens[0], monthText = tokens[1].ToLowerInvariant(), yearText = tokens[2], zone = tokens[4];
        string[] time = tokens[3].Split(':');
        bool validTime = (time.Length == 2 || time.Length == 3) && time.All(piece => Digits(piece, 2));
        if (!Digits(dayText, 1, 2) || !Months.Contains(monthText) || !Digits(yearText, 2, 4) || !validTime || !(NumericZone(zone) || Zones.ContainsKey(zone.ToLowerInvariant()))) return Failure("bad Date syntax");
        int day = int.Parse(dayText), month = Array.IndexOf(Months, monthText) + 1, year = int.Parse(yearText);
        if (yearText.Length == 2) year += year < 50 ? 2000 : 1900;
        int hour = int.Parse(time[0]), minute = int.Parse(time[1]), second = time.Length == 3 ? int.Parse(time[2]) : 0, offset;
        if (NumericZone(zone)) {
            int hours = int.Parse(zone[1..3]), minutes = int.Parse(zone[3..]);
            if (hours > 23 || minutes > 59) return Failure("Date out of range");
            offset = (hours * 60 + minutes) * (zone[0] == '-' ? -1 : 1);
        } else offset = Zones[zone.ToLowerInvariant()];
        if (year < 1970 || year > 2099 || day < 1 || day > MonthDays(year, month) || hour > 23 || minute > 59 || second > 59) return Failure("Date out of range");
        int days = EpochDays(year, month, day);
        long seconds = days * 86400L + hour * 3600 + minute * 60 + second - offset * 60;
        if (seconds < 0) return Failure("Date out of range");
        if (weekday >= 0 && (days + 3) % 7 != weekday) return Failure("Date weekday mismatch");
        return new DateResult(seconds, null);
    }
    public static string Format(long seconds) {
        int days = (int)(seconds / 86400), rest = (int)(seconds % 86400), year = 1970, month = 1;
        while (days >= YearDays(year)) { days -= YearDays(year); year++; }
        while (days >= MonthDays(year, month)) { days -= MonthDays(year, month); month++; }
        return string.Format(CultureInfo.InvariantCulture, "{0:D4}-{1:D2}-{2:D2} {3:D2}:{4:D2}:{5:D2}", year, month, days + 1, rest / 3600, rest % 3600 / 60, rest % 60);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

sealed record SourceLine(int Number, string Text);
sealed record Field(string Name, string Value);
sealed record Token(string Kind, string Text, bool Spaced);
sealed record DecodedWord(string Text, bool Decoded, bool Error);
sealed record Parameters(string Type, string Subtype, Dictionary<string, string> Values);
sealed class Header {
    public readonly List<Field> Fields = new();
    public readonly List<int> Invalid = new();
    public string Value(string name) => Fields.FirstOrDefault(field => field.Name == name.ToLowerInvariant())?.Value;
    public int Count(string name) => Fields.Count(field => field.Name == name.ToLowerInvariant());
}
static class Headers {
    const string AddressSpecials = "<>:;@,.", AddressWords = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&'*+-/=?^_`{|}~";
    const string MimeSpecials = "/;=", MimeExcluded = "()<>@,;:\\\"/[]?=";
    public static bool Whitespace(char letter) => letter == ' ' || letter == '\t';
    public static string Rstrip(string text) => text.TrimEnd(' ', '\t');
    public static string Strip(string text) => text.Trim(' ', '\t');
    public static List<string> Words(string text) => text.Split([' ', '\t'], StringSplitOptions.RemoveEmptyEntries).ToList();
    public static string Collapse(string text) => string.Join(" ", Words(text));
    public static Header ParseFields(List<SourceLine> lines) {
        Header header = new();
        List<string> names = new(), values = new();
        bool inField = false;
        foreach (SourceLine line in lines) {
            string text = line.Text;
            if (Whitespace(text[0])) {
                if (inField) values[^1] += text; else header.Invalid.Add(line.Number);
                continue;
            }
            int split = text.IndexOf(':');
            string name = split < 0 ? "" : text[..split];
            inField = name.Length > 0 && name.All(letter => letter >= 33 && letter <= 126);
            if (inField) { names.Add(name.ToLowerInvariant()); values.Add(text[(split + 1)..]); }
            else header.Invalid.Add(line.Number);
        }
        for (int i = 0; i < names.Count; i++) header.Fields.Add(new Field(names[i], Strip(values[i])));
        return header;
    }
    public static string RemoveComments(string text) {
        StringBuilder result = new();
        int depth = 0;
        for (int i = 0; i < text.Length; i++) {
            char letter = text[i];
            if (depth == 0) { if (letter == '(') { depth = 1; result.Append(' '); } else result.Append(letter); }
            else if (letter == '\\') i++;
            else if (letter == '(') depth++;
            else if (letter == ')') depth--;
        }
        return depth == 0 ? result.ToString() : null;
    }
    public static List<Token> Tokenize(string text, bool mime) {
        List<Token> tokens = new();
        int position = 0;
        bool spaced = false;
        string specials = mime ? MimeSpecials : AddressSpecials;
        while (position < text.Length) {
            char letter = text[position];
            if (Whitespace(letter)) { spaced = true; position++; continue; }
            if (letter == '(') {
                int depth = 1; position++;
                while (position < text.Length && depth > 0) {
                    char next = text[position++];
                    if (next == '\\') position++;
                    else if (next == '(') depth++;
                    else if (next == ')') depth--;
                }
                if (depth != 0) return null;
                spaced = true;
                continue;
            }
            if (letter == '"') {
                position++;
                StringBuilder value = new();
                bool closed = false;
                while (position < text.Length) {
                    char next = text[position++];
                    if (next == '"') { closed = true; break; }
                    if (next == '\\') { if (position == text.Length) return null; next = text[position++]; }
                    value.Append(next);
                }
                if (!closed) return null;
                tokens.Add(new Token("quoted", value.ToString(), spaced));
            } else if (specials.Contains(letter)) { tokens.Add(new Token(letter.ToString(), letter.ToString(), spaced)); position++; }
            else if (WordCharacter(letter, mime)) {
                int start = position;
                while (position < text.Length && WordCharacter(text[position], mime)) position++;
                tokens.Add(new Token("word", text[start..position], spaced));
            } else return null;
            spaced = false;
        }
        return tokens;
    }
    static bool WordCharacter(char letter, bool mime) => mime ? letter >= 33 && letter <= 126 && !MimeExcluded.Contains(letter) : AddressWords.Contains(letter);
    static string DecodeQ(string text) {
        StringBuilder result = new();
        for (int i = 0; i < text.Length; i++) {
            char letter = text[i];
            if (letter == '_') result.Append(' ');
            else if (letter == '=') {
                if (i + 2 >= text.Length) return null;
                int first = Mime.Hex(text[i + 1]), second = Mime.Hex(text[i + 2]);
                if (first < 0 || second < 0) return null;
                result.Append((char)(first * 16 + second)); i += 2;
            } else result.Append(letter);
        }
        return result.ToString();
    }
    public static DecodedWord DecodeWord(string word) {
        if (word.Length < 4 || !word.StartsWith("=?", StringComparison.Ordinal) || !word.EndsWith("?=", StringComparison.Ordinal)) return new DecodedWord(word, false, false);
        string[] parts = word[2..^2].Split('?');
        if (parts.Length != 3 || parts.Any(part => part.Length == 0)) return new DecodedWord(word, false, false);
        string decoded = null;
        if (parts[0].ToLowerInvariant() == "us-ascii") {
            if (parts[1] is "Q" or "q") decoded = DecodeQ(parts[2]);
            else if (parts[1] is "B" or "b") decoded = Mime.StrictBase64(parts[2]);
        }
        if (decoded == null || !decoded.All(letter => letter >= 32 && letter <= 126)) return new DecodedWord(word, false, true);
        return new DecodedWord(decoded, true, false);
    }
    public static DecodedText Unstructured(string value) {
        StringBuilder text = new();
        bool previous = false, error = false, first = true;
        foreach (string word in Words(value)) {
            DecodedWord decoded = DecodeWord(word);
            if (!first && !(previous && decoded.Decoded)) text.Append(' ');
            text.Append(decoded.Text); previous = decoded.Decoded; error |= decoded.Error; first = false;
        }
        return new DecodedText(Collapse(text.ToString()), error);
    }
    public static Parameters ParseParameters(string value, bool withSubtype) {
        List<Token> tokens = Tokenize(value, true);
        if (tokens == null || tokens.Count == 0 || tokens[0].Kind != "word") return null;
        string type = tokens[0].Text.ToLowerInvariant(), subtype = "";
        int position = 1;
        if (withSubtype) {
            if (tokens.Count < 3 || tokens[1].Kind != "/" || tokens[2].Kind != "word") return null;
            subtype = tokens[2].Text.ToLowerInvariant(); position = 3;
        }
        Dictionary<string, string> values = new(StringComparer.Ordinal);
        while (position < tokens.Count) {
            if (position + 3 >= tokens.Count || tokens[position].Kind != ";" || tokens[position + 1].Kind != "word" || tokens[position + 2].Kind != "=" || tokens[position + 3].Kind is not ("word" or "quoted")) return null;
            values.TryAdd(tokens[position + 1].Text.ToLowerInvariant(), tokens[position + 3].Text);
            position += 4;
        }
        return new Parameters(type, subtype, values);
    }
}

using System.Text;

sealed record DecodedText(string Text, bool Error);
static class Mime {
    const string Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    public static int Hex(char letter) => letter >= '0' && letter <= '9' ? letter - '0' : letter >= 'A' && letter <= 'F' ? letter - 'A' + 10 : letter >= 'a' && letter <= 'f' ? letter - 'a' + 10 : -1;
    public static string StrictBase64(string text) {
        if (text.Length % 4 != 0) return null;
        int end = text.Length;
        while (end > 0 && text[end - 1] == '=') end--;
        if (text.Length - end >= 3) return null;
        StringBuilder result = new();
        int buffer = 0, bits = 0;
        for (int i = 0; i < end; i++) {
            int value = Alphabet.IndexOf(text[i]);
            if (value < 0) return null;
            buffer = buffer << 6 | value; bits += 6;
            if (bits >= 8) { bits -= 8; result.Append((char)(buffer >> bits)); buffer &= (1 << bits) - 1; }
        }
        return result.ToString();
    }
    public static string Base64Body(string text) {
        string data = StrictBase64(text.Replace(" ", "").Replace("\t", "").Replace("\n", ""));
        if (data == null) return null;
        data = data.Replace("\r\n", "\n");
        foreach (char letter in data) if (letter != 9 && letter != 10 && (letter < 32 || letter > 126)) return null;
        return data;
    }
    public static DecodedText QuotedPrintable(string text) {
        string[] lines = text.Split('\n');
        StringBuilder output = new();
        bool error = false;
        for (int i = 0; i < lines.Length; i++) {
            string line = Headers.Rstrip(lines[i]);
            bool soft = line.EndsWith('=');
            if (soft) line = line[..^1];
            for (int position = 0; position < line.Length;) {
                char letter = line[position];
                int value = -1;
                if (letter == '=' && position + 2 < line.Length) {
                    int first = Hex(line[position + 1]), second = Hex(line[position + 2]);
                    if (first >= 0 && second >= 0) { int candidate = first * 16 + second; if (candidate == 9 || candidate >= 32 && candidate <= 126) value = candidate; }
                }
                if (value >= 0) { output.Append((char)value); position += 3; }
                else { output.Append(letter); error |= letter == '='; position++; }
            }
            if (!soft && i + 1 < lines.Length) output.Append('\n');
        }
        return new DecodedText(output.ToString(), error);
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

sealed record Sections(List<SourceLine> Header, List<SourceLine> Body);
sealed record SortKey(int InvalidDate, long Seconds, string Id, int Number) : IComparable<SortKey> {
    public int CompareTo(SortKey other) {
        int result = InvalidDate.CompareTo(other.InvalidDate);
        if (result == 0) result = Seconds.CompareTo(other.Seconds);
        if (result == 0) result = StringComparer.Ordinal.Compare(Id, other.Id);
        return result == 0 ? Number.CompareTo(other.Number) : result;
    }
}
sealed class Entity {
    public readonly string Number;
    public string Type = "text", Subtype = "plain", Disposition, Filename, Content = "";
    public Dictionary<string, string> Parameters = new(StringComparer.Ordinal);
    public List<Entity> Children;
    public Entity(string number) { Number = number; }
    public bool Multipart() => Children != null;
    public string Parameter(string name) => Parameters.GetValueOrDefault(name, "");
}
sealed class Message {
    public readonly int Number;
    public readonly List<string> Problems = new();
    public Mailbox Sender;
    public List<string> To = new(), Cc = new(), References = new();
    public string Subject = "", BaseSubject = "", Id = "";
    public bool Reply;
    public long? Date;
    public Entity Body;
    public SortKey SortKey;
    public int Thread, Depth;
    public Message Parent;
    public Message(int number) { Number = number; }
    public void Problem(string text) => Problems.Add(text);
    public void Process(List<SourceLine> lines, Dictionary<string, int> knownIds) {
        Sections sections = Program.SplitSections(lines);
        Header header = Headers.ParseFields(sections.Header);
        foreach (int line in header.Invalid) Problem("bad header line " + line);
        foreach (string name in Program.CheckedFields) if (header.Count(name) > 1) Problem("duplicate " + name);
        ReadSender(header.Value("From")); To = ReadRecipients(header.Value("To"), "To"); Cc = ReadRecipients(header.Value("Cc"), "Cc");
        ReadSubject(header.Value("Subject")); ReadDate(header.Value("Date")); ReadId(header.Value("Message-ID"), knownIds);
        References = Program.ExtractIds(header.Value("References") ?? "");
        List<string> replies = Program.ExtractIds(header.Value("In-Reply-To") ?? "");
        if (replies.Count > 0 && (References.Count == 0 || References[^1] != replies[0])) References.Add(replies[0]);
        bool mime = MimeEnabled(header.Value("MIME-Version"));
        Body = ParseEntity("1", header, sections.Body, mime);
        SortKey = new SortKey(Date.HasValue ? 0 : 1, Date ?? 0, Id, Number);
    }
    void ReadSender(string value) {
        if (value == null) { Problem("missing From"); return; }
        AddressList parsed = Addresses.Parse(value);
        if (parsed == null || parsed.Addresses.Count != 1 || parsed.Addresses[0] is not Mailbox) { Problem("bad From"); return; }
        Sender = (Mailbox)parsed.Addresses[0];
        if (parsed.EncodingError) Problem("bad encoded word in From");
    }
    List<string> ReadRecipients(string value, string name) {
        List<string> recipients = new();
        if (value == null) return recipients;
        AddressList parsed = Addresses.Parse(value);
        if (parsed == null) { Problem("bad " + name); return recipients; }
        foreach (Address address in parsed.Addresses) {
            if (address is Mailbox mailbox) recipients.Add(mailbox.AddressText);
            else foreach (Address member in ((AddressGroup)address).Mailboxes) recipients.Add(((Mailbox)member).AddressText);
        }
        if (parsed.EncodingError) Problem("bad encoded word in " + name);
        return recipients;
    }
    void ReadSubject(string value) {
        DecodedText decoded = Headers.Unstructured(value ?? "");
        Subject = decoded.Text;
        if (decoded.Error) Problem("bad encoded word in Subject");
        BaseSubject = Subject;
        while (BaseSubject.Length >= 3 && BaseSubject[..3].ToLowerInvariant() == "re:") { BaseSubject = BaseSubject[3..].TrimStart(' '); Reply = true; }
    }
    void ReadDate(string value) {
        if (value == null) { Problem("missing Date"); return; }
        DateResult parsed = Dates.Parse(value);
        if (parsed.Error == null) Date = parsed.Seconds; else Problem(parsed.Error);
    }
    void ReadId(string value, Dictionary<string, int> known) {
        if (value == null) Problem("missing Message-ID");
        else if (!Program.MessageId(value)) Problem("bad Message-ID");
        else if (known.TryGetValue(value, out int first)) Problem("Message-ID already used by message " + first);
        else { Id = value; known.Add(value, Number); }
    }
    bool MimeEnabled(string value) {
        if (value == null) return false;
        string text = Headers.RemoveComments(value);
        if (text != null && text.Replace(" ", "").Replace("\t", "") == "1.0") return true;
        Problem("bad MIME-Version");
        return false;
    }
    Entity ParseEntity(string number, Header header, List<SourceLine> lines, bool mime) {
        Entity entity = new(number);
        string contentType = header.Value("Content-Type");
        if (mime && contentType != null) {
            Parameters parsed = Headers.ParseParameters(contentType, true);
            if (parsed == null) Problem("bad Content-Type in part " + number);
            else { entity.Type = parsed.Type; entity.Subtype = parsed.Subtype; entity.Parameters = parsed.Values; }
        }
        string disposition = header.Value("Content-Disposition");
        if (mime && disposition != null) {
            Parameters parsed = Headers.ParseParameters(disposition, false);
            if (parsed == null) Problem("bad Content-Disposition in part " + number);
            else { entity.Disposition = parsed.Type; entity.Filename = parsed.Values.GetValueOrDefault("filename"); }
        }
        if (string.IsNullOrEmpty(entity.Filename)) entity.Filename = entity.Parameters.GetValueOrDefault("name");
        if (entity.Type == "text" && entity.Parameters.TryGetValue("charset", out string charset) && charset.ToLowerInvariant() != "us-ascii") Problem("unsupported charset \"" + charset.ToLowerInvariant() + "\" in part " + number);
        if (mime && entity.Type == "multipart") {
            string boundary = entity.Parameter("boundary");
            if (boundary.Length > 0) { SplitMultipart(entity, lines, boundary); return entity; }
            Problem("missing boundary in part " + number);
        }
        DecodeLeaf(entity, header, lines, mime);
        return entity;
    }
    void SplitMultipart(Entity entity, List<SourceLine> lines, string boundary) {
        List<List<SourceLine>> parts = new();
        bool closed = false;
        foreach (SourceLine line in lines) {
            string text = Headers.Rstrip(line.Text);
            if (text == "--" + boundary + "--") { closed = true; break; }
            if (text == "--" + boundary) parts.Add(new());
            else if (parts.Count > 0) parts[^1].Add(line);
        }
        if (parts.Count == 0) Problem("no parts in part " + entity.Number);
        else if (!closed) Problem("unterminated multipart in part " + entity.Number);
        entity.Children = new();
        for (int i = 0; i < parts.Count; i++) {
            Sections sections = Program.SplitSections(parts[i]);
            Header header = Headers.ParseFields(sections.Header);
            foreach (int line in header.Invalid) Problem("bad header line " + line);
            entity.Children.Add(ParseEntity(entity.Number + "." + (i + 1), header, sections.Body, true));
        }
    }
    void DecodeLeaf(Entity entity, Header header, List<SourceLine> lines, bool mime) {
        string original = string.Join("\n", lines.Select(line => line.Text));
        string transfer = header.Value("Content-Transfer-Encoding"), encoding = mime && transfer != null ? transfer.ToLowerInvariant() : "7bit";
        if (encoding == "base64") {
            entity.Content = Mime.Base64Body(original);
            if (entity.Content == null) { Problem("bad base64 in part " + entity.Number); entity.Content = ""; }
        } else if (encoding == "quoted-printable") {
            DecodedText decoded = Mime.QuotedPrintable(original); entity.Content = decoded.Text;
            if (decoded.Error) Problem("bad quoted-printable in part " + entity.Number);
        } else {
            entity.Content = original;
